import {SYNC_SCHEMA} from '../sync/schema';
type Params = unknown[] | [Record<string, unknown>];

/** Подготовленный запрос с тем же видом, что был у better-sqlite3: get / all / run. */
export interface Statement {
  get(...params: Params): unknown;
  all(...params: Params): unknown[];
  run(...params: Params): { changes: number | bigint; lastInsertRowid: number | bigint };
}

export interface DB {
  prepare(sql: string): Statement;
  exec(sql: string): void;
  /** Читает или меняет PRAGMA. С { simple: true } вернёт одно значение. */
  pragma(text: string, opts?: { simple?: boolean }): unknown;
  /** Оборачивает функцию в транзакцию: при ошибке всё откатывается. Вложенные вызовы безопасны. */
  transaction<A extends unknown[], R>(fn: (...args: A) => R): (...args: A) => R;
  close(): void;
}


