export function installSchema(db:DB):void {const v=Number(db.pragma('user_version',{simple:true}));if(v>MIGRATIONS.length)throw Error('Нужна новая версия mwave');db.exec('PRAGMA foreign_keys=ON;PRAGMA journal_mode=WAL');for(let n=v;n<MIGRATIONS.length;n++)db.transaction(()=>{db.exec(MIGRATIONS[n]);db.exec('PRAGMA user_version='+(n+1));})();}
